<div class="page-title"><h1><?php echo $template?'Edit':'Create'; ?> template</h1></div><div class="card"><div class="card-body"><form method="post" action="<?php echo site_url('email_marketing/templates/save'); ?>"><input type="hidden" name="<?php echo csrf_token(); ?>" value="<?php echo csrf_hash(); ?>"><div class="form-group"><label>Name</label><input required class="form-control" name="name" value="<?php echo esc($template->name??''); ?>"></div><div class="form-group"><label>Subject</label><input required class="form-control" name="subject" value="<?php echo esc($template->subject??''); ?>"></div><div class="form-group"><label>HTML content</label><textarea required class="form-control" name="html_content" rows="15"><?php echo esc($template->html_content??''); ?></textarea></div><p>Valid variables: <?php echo esc(implode(', ',array_map(fn($v)=>'{'.$v.'}',$vars))); ?></p><button class="btn btn-primary">Save template</button></form></div></div>
